let run_hol_test (name,bs,out,n) =
  let th = DEFLATE_DECODE_RULE bs in
  let expected = list_mk_icomb "deflate_decode"
    [lhand(rator(concl th)); mk_out out; mk_small_numeral n] in
  let ok = aconv (concl th) expected && hyp th = [] in
  Printf.printf "%-45s %s\n%!" name (if ok then "OK" else "WRONG"); ok;;

let hol_tests_ok = forall (fun x -> run_hol_test x) hol_tests;;
